INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2520, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/nie/2026/07/07/DFPMW64FGFFHNKA75FEB7MIF2I/', 'https://www.chosun.com/national/nie/2026/07/07/DFPMW64FGFFHNKA75FEB7MIF2I/', '사회', '[두근두근 뇌 운동] [2902] 암호로 바꿔 쓰기', '', '', 'rss', '조선일보', '2026-07-06 15:34:00', '보수', 'crawl_failed', 'https://www.chosun.com/resizer/v2/HCDT5OFY3FGM7KUFX6YXWSBWE4.jpg?auth=89b4ff4eee558d55392333ed7dec6254dd52dba8ba9877978ff6c05e794b0432&smart=true&width=650&height=985', '2026-07-07 06:04:18', '2026-07-07 15:16:14.347798', NULL);
